(function () {
  'use strict';
  const {projects, sources} = globalThis.MediaInfoProjects;
  const C = globalThis.MediaInfoProjectsCore, e = C.escape;
  const ACCESS_KEY = 'mediainfolab_student_access_v1', PREFIX = 'mediainfolab_projects_v1:';
  let state = C.empty(), owner = '', storageKey = '', storageOK = true, filter = 'Alle', pendingImport = null, toastTimer;
  const $ = s => document.querySelector(s);
  const rfor = p => C.record(state,p);
  const icons = {
    play:'<rect x="8" y="13" width="64" height="46" rx="6"/><path d="m34 26 19 11-19 11z"/><path d="M16 68h48"/>',
    grid:'<rect x="9" y="9" width="62" height="62" rx="7"/><path d="M9 30h62M39 30v41M9 51h30M48 43h14M48 51h14M48 59h9"/>',
    file:'<path d="M24 8h27l14 14v49H24zM51 8v16h14M32 36h24M32 46h24M32 56h17"/><path d="M16 17H9v55"/>',
    search:'<circle cx="34" cy="32" r="22"/><path d="m50 49 22 22M34 19v18M34 42v3"/>',
    bolt:'<path d="M45 5 16 45h23l-5 30 30-44H43z"/>'
  };
  const icon = p => `<svg viewBox="0 0 80 80" aria-hidden="true">${icons[p.icon] || icons.file}</svg>`;
  const list = (items,cls='') => `<ul${cls?` class="${e(cls)}"`:''}>${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`;
  const pill = r => `<span class="status-pill ${r.finishedAt?'done':C.status(r)==='In Arbeit'?'working':''}">${C.status(r)}</span>`;
  function note(p,key,label,placeholder='') {
    return `<label class="note-label" for="note-${e(key)}">${e(label)}</label><textarea class="project-note" id="note-${e(key)}" data-note="${e(key)}" data-project="${p.id}" maxlength="12000" placeholder="${e(placeholder)}">${e(rfor(p).notes[key]||'')}</textarea>`;
  }
  function visibleActions(p,r,actions) {
    const choice = r.choice || p.choices?.[0]?.id;
    if(!choice) return actions;
    const prefixes=p.id==='dokumente'?{scan:'Scanweg:',bilder:'Bildweg:'}:p.id==='tutorial'?{bilder:'Bildanleitung:',video:'Video:'}:null;
    if(!prefixes) return actions;
    return actions.flatMap(a=>a.split(/(?=Scanweg:|Bildweg:|Bildanleitung:|Video:|Für ein Video:)/).filter(Boolean)).filter(a=>{
      const match=Object.entries(prefixes).find(([,prefix])=>a.startsWith(prefix));
      if(a.startsWith('Für ein Video:')) return choice==='video';
      return !match || match[0]===choice;
    });
  }
  function resources(p){return p.resources?`<h3>Ihr Übungsmaterial</h3><p>Öffnen Sie die Dateien in einem neuen Tab. Alle Angaben sind erfundene Übungsdaten.</p><div class="resource-list">${p.resources.map(x=>`<a class="p-button" href="${e(x.href)}" target="_blank" rel="noopener">${e(x.label)} ↗</a>`).join('')}</div>`:'';}
  function sourceList(p){return `<details class="project-sources"><summary>${p.id==='faktencheck'?'Quellenhilfen für Ihre Recherche':'Offizielle Hilfen und Quellen'}</summary><p>Die folgenden Seiten öffnen in einem neuen Tab. Menüs können je nach Gerät und Programmversion anders heissen.</p><ul class="source-list">${sources.filter(s=>s.projects.includes(p.id)).map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a></li>`).join('')}</ul>${p.id==='dokumente'?'<p><a href="index.html#scan-guide" target="_blank" rel="noopener">Scan-Guide auf dieser Webseite öffnen ↗</a></p>':''}</details>`;}
  function pause(p) {return `<details class="project-handoff"><summary>Ich höre für heute auf</summary><p>Speichern Sie zuerst Ihr Produkt im Projektordner in OneDrive. Halten Sie dann kurz fest, wo Sie nächstes Mal weiterarbeiten.</p>${note(p,'pause','Mein nächster Schritt (freiwillig)','Zum Beispiel: Bild für Schritt 3 ergänzen. Meine Datei liegt unter …')}<p class="note-hint">Häkchen und Notizen liegen in diesem Browser. Für einen Gerätewechsel brauchen Sie eine Sicherung.</p><button class="p-button" type="button" data-action="backup">Arbeitsstand als Datei sichern</button></details>`;}
  function catalogue() {
    const active = projects.filter(p=>C.status(rfor(p))==='In Arbeit');
    const shown = projects.filter(p=>filter==='Alle'||p.category===filter);
    return `<section class="project-hero"><div><p class="eyebrow">Ihr nächster Schritt</p><h1>Fertig mit den Aufträgen?<br>Jetzt etwas Eigenes.</h1><p class="hero-line">Wählen Sie ein Projekt, das Sie interessiert. Entdecken Sie etwas Neues und machen Sie etwas daraus, das Sie zeigen oder selbst nutzen können.</p><p>5 Projekte · in Ihrem Tempo · jederzeit weiterarbeiten</p></div><aside class="hero-board" aria-label="So arbeiten Sie"><strong>Von der Idee zum Ergebnis</strong><ol><li>Ein Projekt wählen</li><li>Mit klaren Schritten umsetzen</li><li>Testen, verbessern und zeigen</li></ol></aside></section>
      <section class="project-startline" aria-label="Bevor Sie beginnen"><p><strong>Wann starten?</strong>Sobald Ihre aktuellen Pflichtaufträge erledigt sind oder Herr Marti den Start freigibt.</p><p><strong>Nur noch wenig Zeit?</strong>Auch mit 15–20 Minuten können Sie beginnen. Jedes Projekt nennt einen sinnvollen Zwischenstand.</p><p><strong>Was wird erwartet?</strong>Ein Projekt Ihrer Wahl. Erst den Basisauftrag fertigstellen; danach können Sie vertiefen oder neu wählen.</p></section>
      ${active.length?`<section class="continue-panel"><h2>Hier können Sie weiterarbeiten</h2>${active.map(p=>`<a href="#${p.id}/${C.next(rfor(p),p)}">${e(p.title)} · ${rfor(p).checks.length}/${p.steps.length} Schritte →</a>`).join('')}</section>`:''}
      <div class="catalogue-head"><div><p class="eyebrow">Sie entscheiden</p><h2 id="viewTitle" tabindex="-1">Welches Projekt passt zu Ihnen?</h2></div><div class="filters" role="group" aria-label="Projekte nach Interesse filtern">${['Alle','Erklären','Organisieren','Prüfen','Entdecken'].map(x=>`<button id="filter-${e(x)}" type="button" data-filter="${e(x)}" aria-pressed="${filter===x}">${e(x)}</button>`).join('')}</div></div>
      <p id="filterCount" class="note-hint" role="status">${shown.length} von ${projects.length} Projekten · Alle Projekte beginnen mit einer Kurzübersicht.</p>
      <div class="project-grid">${shown.map(p=>{const r=rfor(p);return `<article class="project-card tone-${p.color}"><div class="card-art"><div><div class="project-number">${p.number}</div><span class="art-caption">${e(p.category)}</span></div>${icon(p)}</div><div class="card-body"><h3><a href="#${p.id}">${e(p.title)}</a></h3><p class="card-subtitle">${e(p.subtitle)}</p><p>${e(p.hook)}</p><p class="card-product"><strong>Das entsteht</strong>${e(p.product)}</p><div class="card-meta"><span>${e(p.duration)}</span><span>·</span><span>${p.steps.length} Schritte</span></div><div class="card-bottom"><a class="project-link" href="#${p.id}">Projekt ansehen →</a>${pill(r)}</div>${C.status(r)==='In Arbeit'?`<p><a class="project-link" href="#${p.id}/${C.next(r,p)}">Bei meinem Stand weiter →</a></p>`:''}</div></article>`}).join('')}</div>
      <section class="catalogue-help"><h2>Gut zu wissen</h2><details><summary>Muss ich alle fünf Projekte bearbeiten?</summary><p>Nein. Wählen Sie ein Projekt, das Sie interessiert. Führen Sie dieses zu einem brauchbaren Ergebnis. Später können Sie ein weiteres Projekt beginnen. Dieser Bereich ist unabhängig von einer bestimmten Unterrichtswoche.</p></details><details><summary>Wie arbeite ich möglichst selbstständig?</summary><p>Lesen Sie zuerst die Kurzübersicht. Öffnen Sie dann einen Schritt, führen Sie ihn im angegebenen Programm aus und prüfen Sie das Ergebnis. Die passende Hilfe steht direkt unter den Anweisungen. Wenn Sie feststecken, sagen Sie konkret: «Bei Schritt … sehe ich …; ich habe bereits … versucht.»</p></details><details><summary>Wo liegen meine Arbeit und meine Häkchen?</summary><p>Ihr eigentliches Produkt erstellen Sie zum Beispiel in OneNote oder PowerPoint und speichern es in Ihrem schulischen OneDrive. Diese Webseite speichert nur Ihre Projekt-Häkchen und freiwilligen Notizen lokal in diesem Browser, getrennt nach eingegebener Schulmail. Es gibt für diese Projekte keine automatische Synchronisation zwischen Geräten und keine automatische Abgabe.</p><p>Vor einem Gerätewechsel wählen Sie oben «Arbeitsstand sichern». Auf dem anderen Gerät verwenden Sie dieselbe Schulmail und «Sicherung laden». Die Sicherung enthält Häkchen und Notizen, keine Bilder, PDFs oder Videos Ihres Produkts.</p></details><details><summary>Wie gebe ich mein Ergebnis ab?</summary><p>Speichern Sie es unter «OneDrive → Informatik → Projekte → Projektname». Zeigen Sie es Herrn Marti. Falls eine passende Teams-Aufgabe vorhanden ist, geben Sie es dort ab. Eine Veröffentlichung auf der Webseite wird separat mit Herrn Marti besprochen.</p></details><details><summary>Darf ich Hilfe oder KI nutzen?</summary><p>Hilfen sind erlaubt. Probieren, entscheiden, testen und erklären müssen Sie selbst. Sie sollen Ihr Ergebnis ohne fremde Hilfe erläutern können. KI-Antworten ersetzen beim Faktencheck keine gelesenen Quellen. Verwenden Sie keine privaten Daten anderer Personen in Beispielen, Screenshots oder KI-Eingaben.</p></details></section>`;
  }
  function shell(p, page, index, content) {
    const r=rfor(p);
    return `<div class="tone-${p.color}"><nav class="crumbs" aria-label="Pfad"><a href="projekte.html">Projekte</a><span aria-hidden="true">/</span><a href="#${p.id}">${e(p.title)}</a>${page==='step'?`<span aria-hidden="true">/</span><span>Schritt ${index+1}</span>`:page==='finish'?'<span aria-hidden="true">/</span><span>Abschluss</span>':''}</nav><header class="project-heading"><p class="eyebrow">Projekt ${p.number} · ${e(p.category)}</p><h1>${e(p.title)}</h1><p>${e(p.subtitle)}</p></header><div class="project-layout"><aside class="project-sidebar"><p class="side-title">Ihr Weg zum Ergebnis</p><progress value="${r.checks.length}" max="${p.steps.length}" aria-label="Erledigte Projektschritte"></progress><p class="side-progress">${r.checks.length} von ${p.steps.length} Schritten abgehakt</p><nav aria-label="Projektschritte"><a href="#${p.id}" ${page==='overview'?'aria-current="page"':''}><span class="step-number">i</span><span>Kurzübersicht</span></a>${p.steps.map((s,i)=>`<a href="#${p.id}/schritt-${i+1}" ${page==='step'&&index===i?'aria-current="page"':''}><span class="step-number ${r.checks.includes(i)?'checked':''}" aria-label="${r.checks.includes(i)?'erledigt':'offen'}">${r.checks.includes(i)?'✓':i+1}</span><span>${e(s.title)}</span></a>`).join('')}<a href="#${p.id}/abschluss" ${page==='finish'?'aria-current="page"':''}><span class="step-number ${r.finishedAt?'checked':''}">${r.finishedAt?'✓':'→'}</span><span>Prüfen & abschliessen</span></a></nav><div class="side-tools"><button type="button" data-action="template" data-project="${p.id}">Projektvorlage öffnen</button><button type="button" data-action="print" data-project="${p.id}">Ganzer Auftrag / Drucken</button><button type="button" data-action="pass" data-project="${p.id}">Mein Projektpass als Text</button></div></aside><div class="project-content">${content}${sourceList(p)}</div></div></div>`;
  }
  function toolbox(p){return p.toolbox?`<section class="content-panel toolbox"><h2>Trickauswahl: direkt ausprobieren</h2><p>Wählen Sie 5 verschiedene Tricks. Öffnen Sie nur die Anleitungen, die Sie gerade brauchen.</p>${p.toolbox.map(t=>`<details><summary>${e(t.title)}</summary><div><p>${e(t.how)}</p><p><strong>Ihr Test:</strong> ${e(t.test)}</p></div></details>`).join('')}</section>`:'';}
  function overview(p) {
    const r=rfor(p), choice=r.choice||p.choices?.[0]?.id;
    return shell(p,'overview',-1,`<section class="content-panel"><p class="eyebrow">Zuerst die Kurzübersicht</p><h2 id="viewTitle" tabindex="-1">Darum geht es</h2><p class="overview-summary">${e(p.summary)}</p><dl class="project-facts"><div><dt>Ihr Ergebnis</dt><dd>${e(p.product)}</dd></div><div><dt>Zeit für den Basisauftrag</dt><dd>${e(p.duration)}<br>Richtwert; Sie können später weiterarbeiten.</dd></div><div><dt>Arbeitsform</dt><dd>${e(p.work)}</dd></div><div><dt>Das lernen Sie</dt><dd>${e(p.learn)}</dd></div></dl><h3>Das brauchen Sie</h3>${list(p.needs)}<div class="first-move"><strong>Ihr erster konkreter Schritt</strong>${e(p.start)}</div><div class="p-actions"><button class="p-button primary" type="button" data-action="start" data-project="${p.id}">${C.status(r)==='Noch offen'?'Projekt beginnen':r.finishedAt?'Ergebnis ansehen':'Bei meinem Stand weiter'} →</button><button class="p-button" type="button" data-action="template" data-project="${p.id}">Projektvorlage öffnen</button>${pill(r)}</div></section>
      <section class="content-panel"><h2>Ihr Plan für heute</h2><p>Die Aufgaben bleiben gleich. Hier sehen Sie, welcher Zwischenstand in Ihrer verbleibenden Zeit sinnvoll ist.</p><div class="time-choice" role="group" aria-label="Verfügbare Arbeitszeit">${[['short','15–20 Minuten'],['medium','30–40 Minuten'],['full','45 Minuten oder mehr']].map(([v,l])=>`<button id="time-${v}" type="button" data-time="${v}" data-project="${p.id}" aria-pressed="${r.time===v}">${l}</button>`).join('')}</div><p class="time-advice" role="status">${e(p.timeboxes[r.time])}</p>${p.choices?`<h3>Welchen Weg wählen Sie?</h3><div class="route-options">${p.choices.map(c=>`<label class="route-option"><input type="radio" id="choice-${c.id}" name="workRoute" data-choice="${c.id}" data-project="${p.id}" ${choice===c.id?'checked':''}><span><strong>${e(c.label)}</strong><small>${e(c.description)}</small></span></label>`).join('')}</div><p class="note-hint">Die Arbeitsschritte passen sich an Ihre Wahl an. Sie können hier jederzeit wechseln.</p>`:''}${note(p,'plan','Mein Thema oder meine Idee (freiwillig)','Ein Satz genügt.')}<p class="note-hint">Ihr Produkt entsteht im Arbeitsprogramm. Die Notizen hier dienen nur Ihrer Orientierung.</p></section>
      <section class="content-panel"><h2>Ideen, mit denen Sie sofort loslegen können</h2><div class="idea-list">${p.ideas.map(([t,d])=>`<div class="idea"><strong>${e(t)}</strong><p>${e(d)}</p></div>`).join('')}</div>${resources(p)}</section>
      <section class="content-panel"><h2>Ein Blick auf das mögliche Ergebnis</h2><div class="example-box"><p class="example-label">Beispiel · zur Orientierung</p><h3>${e(p.exampleTitle)}</h3><p>${e(p.exampleIntro)}</p><div class="example-preview ${p.id}">${p.exampleItems.map(x=>`<div>${e(x)}</div>`).join('')}</div></div><p class="note-hint">Dies ist ein Beispielaufbau, kein Screenshot einer App. Sie erstellen Ihre eigene Fassung.</p></section>${toolbox(p)}
      <section class="content-panel"><h2>Wann ist der Basisauftrag fertig?</h2>${list(p.quality)}<p>Am Schluss haken Sie diese Kriterien selbst ab. Wenn noch etwas fehlt, arbeiten Sie am passenden Schritt weiter.</p><div class="p-actions"><button class="p-button primary" type="button" data-action="start" data-project="${p.id}">Mit dem Projekt weiter →</button></div>${pause(p)}</section>`);
  }
  function stepView(p,index) {
    const r=rfor(p), s=p.steps[index], acts=visibleActions(p,r,s.actions);
    const selected=p.choices?.find(c=>c.id===(r.choice||p.choices[0].id));
    return shell(p,'step',index,`<section class="content-panel"><div class="step-topline"><span>Schritt ${index+1} von ${p.steps.length}</span><span>ca. ${e(s.minutes)}</span></div><h2 id="viewTitle" tabindex="-1">${e(s.title)}</h2><p class="step-goal">${e(s.goal)}</p>${selected?`<p class="note-hint">Ihr Weg: <strong>${e(selected.label)}</strong> · <a href="#${p.id}">Wahl ändern</a></p>`:''}<ol class="action-list">${acts.map(x=>`<li><span>${e(x)}</span></li>`).join('')}</ol><div class="example-box"><p class="example-label">Konkret zum Beispiel</p><p>${e(s.example)}</p></div><div class="help-section"><h3>Hilfe genau für diesen Schritt</h3>${s.help.map(h=>`<details><summary>${e(h.question)}</summary><p>${e(h.answer)}</p></details>`).join('')}</div>${p.id==='dokumente'&&index<3?resources(p):''}${p.id==='lifehacks'&&index<2?`<details class="project-handoff"><summary>Trickauswahl hier öffnen</summary>${p.toolbox.map(t=>`<h3>${e(t.title)}</h3><p>${e(t.how)}</p><p><strong>Test:</strong> ${e(t.test)}</p>`).join('')}</details>`:''}<label class="checkpoint" for="stepCheck"><input id="stepCheck" type="checkbox" data-step="${index}" data-project="${p.id}" ${r.checks.includes(index)?'checked':''}><span><strong>Erst ausführen, dann abhaken</strong>${e(s.checkpoint)}</span></label>${note(p,`step${index}`,'Meine Notiz zu diesem Schritt (freiwillig)','Zum Beispiel: ein Versuch, eine Verbesserung oder eine offene Frage.')}<div class="step-nav"><a class="p-button" href="#${p.id}${index?`/schritt-${index}`:''}">← ${index?'Vorheriger Schritt':'Kurzübersicht'}</a><a class="p-button primary" href="#${p.id}/${index===p.steps.length-1?'abschluss':`schritt-${index+2}`}">${index===p.steps.length-1?'Zur Qualitätskontrolle':'Nächster Schritt'} →</a></div><p class="note-hint">Weitergehen setzt kein Häkchen. Markieren Sie einen Schritt erst, wenn Sie das Ergebnis geprüft haben.</p>${pause(p)}</section>`);
  }
  function finishView(p) {
    const r=rfor(p), eligible=C.eligible(r,p), missing=p.steps.length-r.checks.length;
    return shell(p,'finish',-1,`<section class="content-panel"><p class="eyebrow">Ergebnis vorzeigen können</p><h2 id="viewTitle" tabindex="-1">Prüfen Sie Ihre Arbeit</h2><p>Öffnen Sie Ihr tatsächliches Produkt. Haken Sie nur ab, was Sie daran überprüft haben. Die Webseite bewertet die Qualität nicht automatisch.</p>${missing?`<p class="finish-hint">Noch ${missing} ${missing===1?'Schritt ist':'Schritte sind'} offen. <a href="#${p.id}/${C.next(r,p)}">Zum ersten offenen Schritt →</a></p>`:''}<div class="quality-list">${p.quality.map((q,i)=>`<label class="quality-item" for="quality-${i}"><input type="checkbox" id="quality-${i}" data-quality="${i}" data-project="${p.id}" ${r.quality.includes(i)?'checked':''}><span>${e(q)}</span></label>`).join('')}</div>${note(p,'result','Was habe ich gelernt oder verbessert? (freiwillig)','Ein konkreter Satz genügt.')}<h3>Speichern und abgeben</h3><p>Speichern Sie Ihr Produkt im schulischen OneDrive unter <strong>Informatik → Projekte → Projektname</strong>. Zeigen Sie es Herrn Marti oder geben Sie es in einer vorhandenen Teams-Aufgabe ab. Das Häkchen hier sendet keine Datei an die Lehrperson.</p>${r.finishedAt?'<div class="finish-banner"><strong>Basisauftrag fertig – nach Ihrer eigenen Kontrolle.</strong><p>Sie können eine Vertiefung wählen oder ein weiteres Projekt beginnen.</p></div>':`<p id="finishRequirement" class="note-hint">${eligible?'Alle Schritte und Qualitätskriterien sind abgehakt.':`Für den Abschluss fehlen noch ${missing} Schritte und ${p.quality.length-r.quality.length} Qualitätskriterien.`}</p><button class="p-button primary" type="button" data-action="finish" data-project="${p.id}" aria-describedby="finishRequirement" ${eligible?'':'disabled'}>Basisauftrag als fertig markieren</button>`}<div class="p-actions"><button class="p-button" type="button" data-action="pass" data-project="${p.id}">Mein Projektpass als Text</button><button class="p-button" type="button" data-action="backup">Arbeitsstand sichern</button></div><p class="note-hint">Der Projektpass enthält Ihren Stand und Ihre Notizen. Das eigentliche Produkt speichern und zeigen Sie zusätzlich.</p></section><section class="content-panel"><p class="eyebrow">Freiwillig weiterdenken</p><h2>Noch Zeit und Lust?</h2><p>Wenn Ihr Basisauftrag fertig ist, wählen Sie eine Vertiefung. Hier geht es inhaltlich einen Schritt weiter.</p>${p.extensions.map(x=>`<article class="extension"><h3>${e(x.title)}</h3><span class="duration">${e(x.time)}</span><p>${e(x.text)}</p></article>`).join('')}<a class="project-link" href="projekte.html">Alle Projekte ansehen →</a>${pause(p)}</section>`);
  }
  function printView(p) {
    const r=rfor(p);
    return `<header><p>MedienInfoLab · Projekte · BFF Bern</p><h1>${e(p.title)}</h1><p>${e(p.subtitle)}</p></header><div class="print-meta"><p>${e(p.summary)}</p><p><strong>Ergebnis:</strong> ${e(p.product)}</p><p><strong>Zeit:</strong> ${e(p.duration)} · ${e(p.work)}</p><p><strong>Stand:</strong> ${C.status(r)} · ${r.checks.length}/${p.steps.length} Schritte</p></div><section><h2>Vorbereitung</h2>${list(p.needs)}<p><strong>Ihr erster Schritt:</strong> ${e(p.start)}</p><h3>Wenig Zeit?</h3>${list(Object.values(p.timeboxes))}<h3>Ihre Idee</h3><p class="print-note">${e(r.notes.plan||'Noch keine Notiz.')}</p>${p.resources?`<h3>Übungsmaterial</h3>${list(p.resources.map(x=>x.label+' · https://mediainfolab.com/'+x.href))}`:''}</section>${p.steps.map((s,i)=>`<section class="print-step"><h2>Schritt ${i+1}: ${e(s.title)}</h2><p>${e(s.goal)} · ${e(s.minutes)}</p><ol>${visibleActions(p,r,s.actions).map(x=>`<li>${e(x)}</li>`).join('')}</ol><p><strong>Beispiel:</strong> ${e(s.example)}</p>${s.help.map(h=>`<h3>${e(h.question)}</h3><p>${e(h.answer)}</p>`).join('')}<p><strong>${r.checks.includes(i)?'Erledigt':'Noch offen'}:</strong> ${e(s.checkpoint)}</p>${r.notes[`step${i}`]?`<h3>Meine Notiz</h3><p class="print-note">${e(r.notes[`step${i}`])}</p>`:''}</section>`).join('')}<section class="print-step"><h2>Qualitätskontrolle</h2>${list(p.quality.map((q,i)=>(r.quality.includes(i)?'[x] ':'[ ] ')+q))}<h3>Meine Erkenntnis</h3><p class="print-note">${e(r.notes.result||'Noch keine Notiz.')}</p><h3>Nächstes Mal</h3><p class="print-note">${e(r.notes.pause||'Noch keine Notiz.')}</p><h2>Freiwillige Vertiefungen</h2>${p.extensions.map(x=>`<h3>${e(x.title)} · ${e(x.time)}</h3><p>${e(x.text)}</p>`).join('')}<h2>Vorlage</h2><p class="print-note">${e(p.template)}</p>${p.toolbox?`<h2>Trickauswahl</h2>${p.toolbox.map(t=>`<h3>${e(t.title)}</h3><p>${e(t.how)}</p><p>${e(t.test)}</p>`).join('')}`:''}<h2>Quellen und Hilfen</h2>${list(sources.filter(s=>s.projects.includes(p.id)).map(s=>s.label+' · '+s.url))}</section>`;
  }
  function warn(message) {storageOK=false; const el=$('#storageWarning');if(el){el.hidden=false;el.textContent=message;}saveLabel();}
  function saveLabel(){const el=$('#saveStatus');if(el)el.textContent=storageOK?'Arbeitsstand: lokal in diesem Browser':'Nicht dauerhaft gespeichert – Sicherung herunterladen';}
  function account() {
    let email='';try{email=String(JSON.parse(localStorage.getItem(ACCESS_KEY)||'{}').email||'').trim().toLowerCase();}catch{}
    if(!/^(?:[^\s@]+@stud\.bffbern\.ch|christoph\.marti@bffbern\.ch)$/.test(email))email='';
    if(email===owner)return;
    owner=email;storageKey=owner?PREFIX+owner:'';state=C.empty();storageOK=true;
    $('#storageWarning').hidden=true;
    if(storageKey){try{const raw=localStorage.getItem(storageKey);if(raw)state=C.normalize(JSON.parse(raw),projects);}catch{warn('Ihr gespeicherter Projektstand lässt sich nicht lesen oder der Browserspeicher ist blockiert. Neue Eingaben bleiben vorläufig nur in dieser Sitzung. Sichern Sie sie vor dem Schliessen als Datei.');}}
    saveLabel();render(false);
  }
  function change(p, fn) {
    if(!owner){toast('Bitte geben Sie zuerst Ihre Schulmail ein.');return;}
    if(storageOK){try{const raw=localStorage.getItem(storageKey);if(raw)state=C.normalize(JSON.parse(raw),projects);}catch{warn('Der Browserspeicher ist nicht verfügbar. Sichern Sie Ihren Stand vor dem Schliessen als Datei.');}}
    const now=new Date().toISOString(),r=C.cleanProject(rfor(p),p);fn(r);
    if(!C.eligible(r,p))r.finishedAt='';
    r.updatedAt=now;state.projects[p.id]=r;state.updatedAt=now;
    if(storageOK){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{warn('Der Browser konnte die Änderung nicht dauerhaft speichern. Ihre Eingaben bleiben in dieser Sitzung. Laden Sie jetzt eine Sicherung herunter.');}}
    saveLabel();
  }
  function toast(message){const el=$('#projectToast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000);}
  function render(moveFocus=true){
    const active=document.activeElement,oldId=active?.id,y=globalThis.scrollY||0;
    const r=C.route(location.hash,projects);
    $('#main').innerHTML=!r.project?catalogue():r.page==='overview'?overview(r.project):r.page==='step'?stepView(r.project,r.index):finishView(r.project);
    document.title=r.project?`${r.project.title} · Projekte · MedienInfoLab`:'Projekte · MedienInfoLab';
    if(moveFocus){$('#viewTitle')?.focus({preventScroll:true});globalThis.scrollTo?.(0,0);}else if(oldId){document.getElementById(oldId)?.focus({preventScroll:true});globalThis.scrollTo?.(0,y);}
  }
  function download(name,content,type='text/plain;charset=utf-8') {
    const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  function backup(){if(!owner){toast('Bitte geben Sie zuerst Ihre Schulmail ein.');return;}const stamp=new Date().toISOString().replace(/[:.]/g,'-');download(`MedienInfoLab-Projekte-${stamp}.json`,C.encode(state,projects,owner),'application/json');toast('Sicherung erstellt. Sie enthält Häkchen und Notizen; speichern Sie Ihr Produkt zusätzlich in OneDrive.');}
  function dialog(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#projectDialog').showModal();}
  function projectPass(p){const r=rfor(p);return `${p.title}\n${p.subtitle}\n\nStand: ${C.status(r)}\n${r.checks.length} von ${p.steps.length} Schritten\n\nMEINE IDEE\n${r.notes.plan||'–'}\n\n${p.steps.map((s,i)=>`${r.checks.includes(i)?'[x]':'[ ]'} Schritt ${i+1}: ${s.title}\n${r.notes[`step${i}`]||''}`).join('\n\n')}\n\nQUALITÄTSCHECK\n${p.quality.map((q,i)=>`${r.quality.includes(i)?'[x]':'[ ]'} ${q}`).join('\n')}\n\nMEINE ERKENNTNIS / VERBESSERUNG\n${r.notes.result||'–'}\n\nNÄCHSTER SCHRITT\n${r.notes.pause||'–'}\n\nDieser Pass enthält keine Produktdateien. PDF, Video oder OneNote-Ergebnis zusätzlich speichern und zeigen.\n`;}
  function setLarge(on){document.documentElement.classList.toggle('portal-large',on);$('#projectFont').setAttribute('aria-pressed',String(on));$('#projectFont').textContent=on?'A−':'A+';try{const ui=JSON.parse(localStorage.getItem('informatikPortal_ui_v1')||'{}');localStorage.setItem('informatikPortal_ui_v1',JSON.stringify({...ui,largeText:on}));}catch{}}
  function start(){
    account();render(false);try{setLarge(!!JSON.parse(localStorage.getItem('informatikPortal_ui_v1')||'{}').largeText);}catch{}
    $('#projectFont').addEventListener('click',()=>setLarge(!document.documentElement.classList.contains('portal-large')));
    document.addEventListener('submit',()=>account());
    document.addEventListener('input',event=>{const el=event.target,p=projects.find(p=>p.id===el.dataset?.project);if(p&&el.dataset.note){change(p,r=>{r.notes[el.dataset.note]=el.value.slice(0,12000);r.startedAt ||= new Date().toISOString();});}});
    document.addEventListener('change',event=>{
      const el=event.target,p=projects.find(p=>p.id===el.dataset?.project);if(!p)return;
      if(el.hasAttribute('data-step')||el.hasAttribute('data-quality')){const key=el.hasAttribute('data-step')?'checks':'quality',i=Number(el.dataset.step??el.dataset.quality);change(p,r=>{r[key]=el.checked?[...new Set([...r[key],i])]:r[key].filter(x=>x!==i);r.startedAt ||= new Date().toISOString();});render(false);}
      if(el.dataset.choice){change(p,r=>{r.choice=el.dataset.choice;});render(false);}
    });
    document.addEventListener('click',async event=>{
      const button=event.target.closest('button');if(!button)return;
      if(button.dataset.filter){filter=button.dataset.filter;render(false);return;}
      const p=projects.find(p=>p.id===button.dataset.project);
      if(button.dataset.time&&p){change(p,r=>{r.time=button.dataset.time;});render(false);return;}
      switch(button.dataset.action){
        case 'start': if(p){change(p,r=>{r.startedAt ||= new Date().toISOString();r.choice ||= p.choices?.[0]?.id||'';});location.hash=`${p.id}/${rfor(p).finishedAt?'abschluss':C.next(rfor(p),p)}`;}break;
        case 'finish': if(p&&C.eligible(rfor(p),p)){change(p,r=>{r.finishedAt=new Date().toISOString();});render(false);toast('Basisauftrag als fertig markiert. Denken Sie daran, Ihr Produkt zu zeigen oder abzugeben.');}break;
        case 'backup': backup();break;
        case 'import': $('#importProjectFile').value='';$('#importProjectFile').click();break;
        case 'close-dialog': $('#projectDialog').close();pendingImport=null;break;
        case 'confirm-import': if(pendingImport&&storageKey){state=pendingImport;pendingImport=null;try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;$('#storageWarning').hidden=true;}catch{warn('Die Sicherung wurde in diese Sitzung geladen. Der Browser kann sie aber nicht dauerhaft speichern. Behalten Sie Ihre Sicherungsdatei.');}$('#projectDialog').close();saveLabel();render(false);toast('Projektstand aus der Sicherung übernommen.');}break;
        case 'storage-help':dialog('Wo wird was gespeichert?','<p><strong>Ihr Produkt:</strong> Speichern Sie PDF, Video, Präsentation oder OneNote-Seite im schulischen OneDrive.</p><p><strong>Auf dieser Webseite:</strong> Häkchen und freiwillige Notizen werden lokal in diesem Browser gespeichert, getrennt nach der eingegebenen Schulmail. Sie werden nicht automatisch auf ein anderes Gerät oder in den Lehrpersonenbereich übertragen.</p><p><strong>Gerät wechseln:</strong> «Arbeitsstand sichern», Datei in OneDrive ablegen, am anderen Gerät dieselbe Schulmail verwenden und «Sicherung laden» wählen.</p><p>Das Löschen der Browserdaten kann den lokalen Stand entfernen. Die Projekt-Sicherung enthält keine Produktdateien. Die Eingabe der Schulmail ist keine Passwortsperre; verwenden Sie für persönliche Arbeit Ihr eigenes Browserprofil.</p>');break;
        case 'template':if(p)dialog('Projektvorlage',`<p>Kopieren Sie diese Vorlage in Ihr Arbeitsprogramm und füllen Sie die passenden Felder aus. Sie können den Text auch als Datei herunterladen.</p><label for="templateText">Vorlage für «${e(p.title)}»</label><textarea id="templateText" class="template-text" readonly>${e(p.template)}</textarea><div class="p-actions"><button class="p-button primary" type="button" data-action="copy-template">Vorlage kopieren</button><button class="p-button" type="button" data-action="download-template" data-project="${p.id}">Als Textdatei herunterladen</button></div>`);break;
        case 'copy-template':{const field=$('#templateText');try{await navigator.clipboard.writeText(field.value);toast('Vorlage kopiert. Fügen Sie sie jetzt in Ihr Arbeitsprogramm ein.');}catch{field.focus();field.select();toast('Der Text ist markiert. Kopieren Sie mit Strg + C oder Cmd + C.');}break;}
        case 'download-template':if(p)download(`${p.id}-Projektvorlage.txt`,p.template);break;
        case 'pass':if(p)download(`${p.id}-Mein-Projektpass.txt`,projectPass(p));break;
        case 'print':if(p){$('#printProject').innerHTML=printView(p);globalThis.print();}break;
      }
    });
    $('#importProjectFile').addEventListener('change',async event=>{
      const file=event.target.files?.[0];if(!file)return;
      try{if(!owner)throw new Error('Bitte geben Sie zuerst Ihre Schulmail ein.');if(file.size>3000000)throw new Error('Diese Datei ist zu gross für eine Projektsicherung.');pendingImport=C.decode(await file.text(),projects,owner);const n=Object.keys(pendingImport.projects).length;dialog('Sicherung übernehmen?',`<p>Datei: <strong>${e(file.name)}</strong></p><p>Enthält ${n} Projektstände. Die Übernahme ersetzt Ihre jetzigen Projekt-Häkchen und Notizen in diesem Browser. Andere Workshops und Ihre Produktdateien werden nicht verändert.</p><div class="p-actions"><button class="p-button" type="button" data-action="backup">Jetzigen Stand zuerst sichern</button><button class="p-button primary" type="button" data-action="confirm-import">Diese Sicherung übernehmen</button></div>`);}catch(error){pendingImport=null;toast(error.message);}
    });
    globalThis.addEventListener('hashchange',()=>{if($('#projectDialog').open)$('#projectDialog').close();pendingImport=null;render(true);});
    globalThis.addEventListener('storage',event=>{if(event.key===ACCESS_KEY){account();return;}if(event.key===storageKey){try{state=event.newValue?C.normalize(JSON.parse(event.newValue),projects):C.empty();render(false);}catch{warn('Ein anderer Tab hat einen unlesbaren Stand gespeichert. Ihre aktuellen Eingaben bleiben in dieser Sitzung.');}}});
  }
  // Pure markup entry points also support automated structural checks without a browser.
  globalThis.MediaInfoProjectViews={catalogue,overview,stepView,finishView,printView,visibleActions};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
